<?php
namespace Tests\Feature;
use App\Models\Booking;use App\Models\Branch;use App\Models\Customer;use App\Models\Organization;use App\Models\StorageLocation;use App\Models\TireSet;use App\Models\User;use App\Models\Vehicle;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Str;use Tests\TestCase;
class WorkdayTest extends TestCase{use RefreshDatabase;private function fixture():array{$org=Organization::create(['public_id'=>Str::uuid(),'name'=>'Arbeid AS']);$branch=Branch::create(['public_id'=>Str::uuid(),'organization_id'=>$org->id,'name'=>'Hoved','code'=>'HOVED']);$user=User::factory()->create(['organization_id'=>$org->id,'branch_id'=>$branch->id,'role'=>'technician','active'=>true]);$customer=Customer::create(['public_id'=>Str::uuid(),'organization_id'=>$org->id,'branch_id'=>$branch->id,'customer_number'=>'K1','name'=>'Kunde']);$vehicle=Vehicle::create(['public_id'=>Str::uuid(),'organization_id'=>$org->id,'customer_id'=>$customer->id,'registration_number'=>'EV12345']);$location=StorageLocation::create(['public_id'=>Str::uuid(),'organization_id'=>$org->id,'branch_id'=>$branch->id,'code'=>'A-01','capacity'=>20,'active'=>true]);$receiving=StorageLocation::create(['public_id'=>Str::uuid(),'organization_id'=>$org->id,'branch_id'=>$branch->id,'code'=>'MOTTAK','location_type'=>'receiving','capacity'=>20,'active'=>true]);$set=TireSet::create(['public_id'=>Str::uuid(),'organization_id'=>$org->id,'vehicle_id'=>$vehicle->id,'storage_location_id'=>$location->id,'storage_shelf_number'=>2,'code'=>'HJ-SCAN123','season'=>'winter','kind'=>'complete_wheels','quantity'=>4,'status'=>'stored']);return compact('org','branch','user','customer','vehicle','set','receiving');}
public function test_employee_sees_own_hours_and_tomorrows_wheel_location():void{$d=$this->fixture();Booking::create(['public_id'=>Str::uuid(),'organization_id'=>$d['org']->id,'branch_id'=>$d['branch']->id,'assigned_user_id'=>$d['user']->id,'customer_id'=>$d['customer']->id,'vehicle_id'=>$d['vehicle']->id,'reference'=>'I-DAG','service_name'=>'Skift','starts_at'=>now()->setTime(10,0),'ends_at'=>now()->setTime(10,45)]);Booking::create(['public_id'=>Str::uuid(),'organization_id'=>$d['org']->id,'branch_id'=>$d['branch']->id,'customer_id'=>$d['customer']->id,'vehicle_id'=>$d['vehicle']->id,'reference'=>'I-MORGEN','service_name'=>'Skift','starts_at'=>now()->addDay()->setTime(9,0),'ends_at'=>now()->addDay()->setTime(9,45)]);$this->actingAs($d['user'])->get('/min-arbeidsdag')->assertOk()->assertSee('Timene dine')->assertSee('EV12345')->assertSee('A-01')->assertSee('HJ-SCAN123');}
public function test_one_scan_moves_the_entire_wheel_set():void{$d=$this->fixture();$this->actingAs($d['user'])->get('/min-arbeidsdag?code=HJ-SCAN123')->assertOk()->assertSee('4 hjul')->assertSee('Én handling gjelder hele settet');$this->actingAs($d['user'])->patch(route('workday.move',$d['set']),['status'=>'picked'])->assertRedirect();$this->assertDatabaseHas('tire_sets',['id'=>$d['set']->id,'status'=>'picked','quantity'=>4,'storage_location_id'=>$d['receiving']->id,'storage_shelf_number'=>null]);$this->assertDatabaseHas('storage_location_movements',['tire_set_id'=>$d['set']->id,'from_location_id'=>$d['set']->storage_location_id,'to_location_id'=>$d['receiving']->id,'reason'=>'prepared_for_booking']);$this->assertDatabaseHas('audit_logs',['subject_id'=>$d['set']->id,'action'=>'tire_set.workflow.picked']);}
public function test_preparation_can_show_the_next_seven_days():void{$d=$this->fixture();$later=now()->addDays(5)->setTime(9,0);Booking::create(['public_id'=>Str::uuid(),'organization_id'=>$d['org']->id,'branch_id'=>$d['branch']->id,'customer_id'=>$d['customer']->id,'vehicle_id'=>$d['vehicle']->id,'reference'=>'DENNE-UKEN','service_name'=>'Sesongskift','starts_at'=>$later,'ends_at'=>$later->copy()->addMinutes(45)]);$this->actingAs($d['user'])->get(route('workday',['prep'=>'tomorrow']))->assertOk()->assertDontSee('Sesongskift');$this->actingAs($d['user'])->get(route('workday',['prep'=>'week']))->assertOk()->assertSee('Sesongskift')->assertSee('Plukket og lagt på mottak');}}
